-- What the hub decides an ask by (`asks.record`, the whole ask as JSON,
-- core asks.ts) is columns of its row: `kind`, `routed_to_parent`,
-- `answered_at`, `answer_behavior`, `carried_started_at`,
-- `carried_ended_at`, `withdrawn_at`, `used_at` and `lapsed_at`. A permit's
-- grant is found by them alone (db/asks.ts `grants`: approved, allowed,
-- neither spent nor lapsed), and so is a call the hub went while running
-- (`cutShort`: started, never ended). What was asked, who answered and what
-- the call said stay JSON, in `kept` (core `ASK_KEPT`): the record less
-- each value a column holds.
--
-- `record` was NOT NULL from its first migration: every ask has one. A
-- record reads whole as the hub read it (core `ASK_RECORD`): an object
-- whose `asked` is an approve ask's (tool, input, who carries it, its
-- source's facts), a question's (one or more questions in the house shape,
-- whether work waits) or a permit's (tool, input), and whose `toolUseId`,
-- `routedTo` ("parent"), `answer` (when, who, and an allow with a
-- question's answers or a deny with its message), `carried` (started,
-- ended, said, failed), `withdrawn`, `used` and `lapsed` are each missing
-- or of their shape. Such a record is placed as it is: each value in its
-- column, a part never set (no answer, no grant spent, not routed) the
-- column's "not set" (null; `routed_to_parent` false), and the rest kept.
-- Nothing is recomputed.
--
-- A record that is there and does not read whole (not JSON, not an object,
-- or a part of another shape) is never read as an ask: it is kept as
-- stored in `record_unread`, `kept` null, and each value of it that reads
-- is placed in its column, an answer that allowed aside: such a row is
-- never "answered allow", so never a permit's grant, and a call it started
-- and never ended is never found as cut short, so it is never told or run
-- again. An open one is withdrawn as the hub starts, and its session told
-- that it was withdrawn unanswered (asks.ts `boot`). Today's reader threw
-- on such a record. The step before this migration (db/migrate.ts
-- `asks-unread`) logs each by its id, its session and why.
--
-- Every JSON function sits inside a CASE that proved `record` JSON and an
-- object: SQLite may run either side of an AND first. Inside it every
-- path is read off the proved record, a list's entries by their own paths.
DROP INDEX `asks_instance`;--> statement-breakpoint
ALTER TABLE `asks` ADD `kind` text;--> statement-breakpoint
ALTER TABLE `asks` ADD `routed_to_parent` integer DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE `asks` ADD `answered_at` integer;--> statement-breakpoint
ALTER TABLE `asks` ADD `answer_behavior` text;--> statement-breakpoint
ALTER TABLE `asks` ADD `carried_started_at` integer;--> statement-breakpoint
ALTER TABLE `asks` ADD `carried_ended_at` integer;--> statement-breakpoint
ALTER TABLE `asks` ADD `withdrawn_at` integer;--> statement-breakpoint
ALTER TABLE `asks` ADD `used_at` integer;--> statement-breakpoint
ALTER TABLE `asks` ADD `lapsed_at` integer;--> statement-breakpoint
ALTER TABLE `asks` ADD `kept` text;--> statement-breakpoint
ALTER TABLE `asks` ADD `record_unread` text;--> statement-breakpoint
UPDATE `asks` SET `record_unread` = CASE WHEN CASE WHEN json_valid(record) THEN CASE WHEN json_type(record) = 'object' THEN coalesce((json_type(record, '$.toolUseId') IS NULL OR json_type(record, '$.toolUseId') = 'text') AND (json_type(record, '$.asked') = 'object' AND CASE WHEN json_type(record, '$.asked.kind') = 'text' THEN CASE json_extract(record, '$.asked.kind') WHEN 'approve' THEN json_type(record, '$.asked.tool') = 'text' AND json_type(record, '$.asked.input') = 'object' AND json_type(record, '$.asked.carry') = 'object' AND (json_type(record, '$.asked.carry.by') = 'text' AND json_extract(record, '$.asked.carry.by') IN ('hub')) AND json_type(record, '$.asked.carry.tool') = 'text' AND (json_type(record, '$.asked.source') IS NULL OR (json_type(record, '$.asked.source') = 'object' AND json_type(record, '$.asked.source.at') = 'text' AND (json_type(record, '$.asked.source.since') IS NULL OR json_type(record, '$.asked.source.since') = 'text') AND (json_type(record, '$.asked.source.stars') IS NULL OR json_type(record, '$.asked.source.stars') IN ('integer', 'real')) AND (json_type(record, '$.asked.source.unknown') IS NULL OR json_type(record, '$.asked.source.unknown') = 'text') AND (json_type(record, '$.asked.source.weeklyDownloads') IS NULL OR json_type(record, '$.asked.source.weeklyDownloads') IN ('integer', 'real')) AND (json_type(record, '$.asked.source.skill') IS NULL OR (json_type(record, '$.asked.source.skill') = 'object' AND json_type(record, '$.asked.source.skill.description') = 'text' AND json_type(record, '$.asked.source.skill.hash') = 'text' AND json_type(record, '$.asked.source.skill.name') = 'text' AND (json_type(record, '$.asked.source.skill.files') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(record, '$.asked.source.skill.files') f WHERE NOT coalesce(json_type(record, f.fullkey) = 'object' AND json_type(record, f.fullkey || '.hash') = 'text' AND json_type(record, f.fullkey || '.path') = 'text', 0))))))) WHEN 'question' THEN json_array_length(record, '$.asked.questions') >= 1 AND (json_type(record, '$.asked.questions') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(record, '$.asked.questions') q WHERE NOT coalesce(json_type(record, q.fullkey) = 'object' AND json_type(record, q.fullkey || '.header') = 'text' AND json_type(record, q.fullkey || '.multiSelect') IN ('true', 'false') AND json_type(record, q.fullkey || '.question') = 'text' AND json_type(record, q.fullkey || '.options') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(record, q.fullkey || '.options') o WHERE NOT coalesce(json_type(record, o.fullkey) = 'object' AND json_type(record, o.fullkey || '.label') = 'text' AND json_type(record, o.fullkey || '.description') = 'text', 0)), 0))) AND json_type(record, '$.asked.blocks') IN ('true', 'false') AND (json_type(record, '$.asked.waiting') IS NULL OR json_type(record, '$.asked.waiting') = 'text') AND (json_type(record, '$.asked.meanwhile') IS NULL OR json_type(record, '$.asked.meanwhile') = 'text') WHEN 'permit' THEN json_type(record, '$.asked.tool') = 'text' AND json_type(record, '$.asked.input') = 'object' ELSE 0 END ELSE 0 END) AND (json_type(record, '$.routedTo') IS NULL OR (json_type(record, '$.routedTo') = 'text' AND json_extract(record, '$.routedTo') IN ('parent'))) AND (json_type(record, '$.answer') IS NULL OR (json_type(record, '$.answer') = 'object' AND json_type(record, '$.answer.at') IN ('integer', 'real') AND json_type(record, '$.answer.by') = 'object' AND (json_type(record, '$.answer.by.behavior') IS NULL OR (json_type(record, '$.answer.by.behavior') = 'text' AND json_extract(record, '$.answer.by.behavior') IN ('allow', 'deny'))) AND (json_type(record, '$.answer.by.name') IS NULL OR json_type(record, '$.answer.by.name') = 'text') AND (json_type(record, '$.answer.by.via') = 'text' AND json_extract(record, '$.answer.by.via') IN ('page', 'app', 'session', 'harness', 'fullSend')) AND json_type(record, '$.answer.result') = 'object' AND CASE WHEN json_type(record, '$.answer.result.behavior') = 'text' THEN CASE json_extract(record, '$.answer.result.behavior') WHEN 'allow' THEN (json_type(record, '$.answer.result.answers') IS NULL OR (json_type(record, '$.answer.result.answers') = 'object' AND NOT EXISTS (SELECT 1 FROM json_each(record, '$.answer.result.answers') a WHERE NOT CASE a.type WHEN 'text' THEN 1 WHEN 'array' THEN NOT EXISTS (SELECT 1 FROM json_each(a.value) x WHERE x.type <> 'text') ELSE 0 END))) WHEN 'deny' THEN json_type(record, '$.answer.result.message') = 'text' ELSE 0 END ELSE 0 END)) AND (json_type(record, '$.carried') IS NULL OR (json_type(record, '$.carried') = 'object' AND json_type(record, '$.carried.startedAt') IN ('integer', 'real') AND (json_type(record, '$.carried.endedAt') IS NULL OR json_type(record, '$.carried.endedAt') IN ('integer', 'real')) AND (json_type(record, '$.carried.said') IS NULL OR json_type(record, '$.carried.said') = 'text') AND (json_type(record, '$.carried.failed') IS NULL OR json_type(record, '$.carried.failed') = 'text'))) AND (json_type(record, '$.withdrawn') IS NULL OR (json_type(record, '$.withdrawn') = 'object' AND json_type(record, '$.withdrawn.at') IN ('integer', 'real') AND (json_type(record, '$.withdrawn.by') = 'text' AND json_extract(record, '$.withdrawn.by') IN ('hub')) AND json_type(record, '$.withdrawn.why') = 'text')) AND (json_type(record, '$.used') IS NULL OR (json_type(record, '$.used') = 'object' AND json_type(record, '$.used.at') IN ('integer', 'real'))) AND (json_type(record, '$.lapsed') IS NULL OR (json_type(record, '$.lapsed') = 'object' AND json_type(record, '$.lapsed.at') IN ('integer', 'real'))), 0) ELSE 0 END ELSE 0 END THEN NULL ELSE CAST(record AS TEXT) END;--> statement-breakpoint
UPDATE `asks` SET `kind` = CASE WHEN CASE WHEN json_valid(record) THEN json_type(record) = 'object' ELSE 0 END THEN CASE WHEN (json_type(record, '$.asked.kind') = 'text' AND json_extract(record, '$.asked.kind') IN ('approve', 'question', 'permit')) THEN json_extract(record, '$.asked.kind') END END, `routed_to_parent` = coalesce(CASE WHEN CASE WHEN json_valid(record) THEN json_type(record) = 'object' ELSE 0 END THEN (json_type(record, '$.routedTo') = 'text' AND json_extract(record, '$.routedTo') IN ('parent')) END, 0), `answered_at` = CASE WHEN CASE WHEN json_valid(record) THEN json_type(record) = 'object' ELSE 0 END THEN CASE WHEN json_type(record, '$.answer.at') IN ('integer', 'real') THEN json_extract(record, '$.answer.at') END END, `answer_behavior` = CASE WHEN CASE WHEN json_valid(record) THEN json_type(record) = 'object' ELSE 0 END THEN CASE WHEN record_unread IS NULL THEN json_extract(record, '$.answer.result.behavior') WHEN (json_type(record, '$.answer.result.behavior') = 'text' AND json_extract(record, '$.answer.result.behavior') IN ('deny')) THEN 'deny' END END, `carried_started_at` = CASE WHEN CASE WHEN json_valid(record) THEN json_type(record) = 'object' ELSE 0 END THEN CASE WHEN json_type(record, '$.carried.startedAt') IN ('integer', 'real') THEN json_extract(record, '$.carried.startedAt') END END, `carried_ended_at` = CASE WHEN CASE WHEN json_valid(record) THEN json_type(record) = 'object' ELSE 0 END THEN CASE WHEN json_type(record, '$.carried.endedAt') IN ('integer', 'real') THEN json_extract(record, '$.carried.endedAt') END END, `withdrawn_at` = CASE WHEN CASE WHEN json_valid(record) THEN json_type(record) = 'object' ELSE 0 END THEN CASE WHEN json_type(record, '$.withdrawn.at') IN ('integer', 'real') THEN json_extract(record, '$.withdrawn.at') END END, `used_at` = CASE WHEN CASE WHEN json_valid(record) THEN json_type(record) = 'object' ELSE 0 END THEN CASE WHEN json_type(record, '$.used.at') IN ('integer', 'real') THEN json_extract(record, '$.used.at') END END, `lapsed_at` = CASE WHEN CASE WHEN json_valid(record) THEN json_type(record) = 'object' ELSE 0 END THEN CASE WHEN json_type(record, '$.lapsed.at') IN ('integer', 'real') THEN json_extract(record, '$.lapsed.at') END END, `kept` = CASE WHEN CASE WHEN json_valid(record) THEN json_type(record) = 'object' ELSE 0 END THEN CASE WHEN record_unread IS NULL THEN json_remove(record, '$.asked.kind', '$.routedTo', '$.answer.at', '$.answer.result.behavior', '$.carried.startedAt', '$.carried.endedAt', '$.withdrawn.at', '$.withdrawn.by', '$.used', '$.lapsed') END END;--> statement-breakpoint
CREATE INDEX `asks_instance_state_kind` ON `asks` (`instance_id`,`state`,`kind`);--> statement-breakpoint
ALTER TABLE `asks` DROP COLUMN `record`;